const { contextBridge, ipcRenderer } = require('electron');

// Only real cross-process operations go through here. The data model and
// query engine run directly in the renderer (loaded as a plain script,
// vendor-bundle.js, generated by main.js on every launch) because
// contextBridge clones arguments across the isolation boundary rather than
// passing them by reference — a function exposed here that mutates an
// object argument would only ever mutate a throwaway clone, never the
// renderer's real campaign object.
contextBridge.exposeInMainWorld('core', {
  loadCampaign: () => ipcRenderer.invoke('campaign:load'),
  saveCampaign: (campaign) => ipcRenderer.invoke('campaign:save', campaign),
  backupNow: () => ipcRenderer.invoke('campaign:backupNow'),
  campaignLocation: () => ipcRenderer.invoke('campaign:location'),
  logDiagnostic: (kind, details) => ipcRenderer.invoke('diagnostics:log', { kind, details }),
  onSaveStatus: (cb) => ipcRenderer.on('save-status', (_e, status) => cb(status)),

  getImagesBaseUrl: () => ipcRenderer.invoke('image:baseUrl'),
  findArtwork: (name) => ipcRenderer.invoke('artwork:find', name),
  readArtwork: (filePath) => ipcRenderer.invoke('artwork:read', filePath),
  pickImageSource: () => ipcRenderer.invoke('image:pickSource'),
  saveCroppedEntityImage: (entityId, dataUrl) => ipcRenderer.invoke('image:saveCropped', { entityId, dataUrl }),
  removeEntityImageFile: (filename) => ipcRenderer.invoke('image:remove', { filename }),

  transferTargets: () => ipcRenderer.invoke('transfer:listTargets'),
  transferPreview: (targetIds, entries) => ipcRenderer.invoke('transfer:preview', { targetIds, entries }),
  transferRun: (targetIds, entries) => ipcRenderer.invoke('transfer:run', { targetIds, entries }),
  listCampaigns: () => ipcRenderer.invoke('campaign:list'),
  activeCampaignInfo: () => ipcRenderer.invoke('campaign:activeInfo'),
  createCampaign: (name) => ipcRenderer.invoke('campaign:create', { name }),
  switchCampaign: (id) => ipcRenderer.invoke('campaign:switch', id),
  renameCampaign: (id, name) => ipcRenderer.invoke('campaign:rename', { id, name }),
  deleteCampaign: (id) => ipcRenderer.invoke('campaign:delete', id),

  openNotionLink: (url) => ipcRenderer.invoke('notion:open', url),

  getSettings: () => ipcRenderer.invoke('settings:get'),
  saveSettings: (settings) => ipcRenderer.invoke('settings:save', settings),
  pickFolder: () => ipcRenderer.invoke('settings:pickFolder'),

  listDirectorSessions: () => ipcRenderer.invoke('director:listSessions'),
  listDirectorScenes: (session) => ipcRenderer.invoke('director:listScenes', session),
  listDirectorLayouts: (session, scene) => ipcRenderer.invoke('director:listLayouts', { session, scene }),
  listDirectorAllScenes: () => ipcRenderer.invoke('director:listAllScenes'),
  listDirectorMusic: (session, scene) => ipcRenderer.invoke('director:listMusic', { session, scene }),
  listDirectorQuickfire: (session, scene) => ipcRenderer.invoke('director:listQuickfire', { session, scene }),
  listDirectorGenres: () => ipcRenderer.invoke('director:listGenres'),
  listDirectorGenreTracks: (genre) => ipcRenderer.invoke('director:listGenreTracks', genre),
  listDirectorPlaylists: () => ipcRenderer.invoke('director:listPlaylists'),
  listDirectorPlaylistTracks: (item) => ipcRenderer.invoke('director:listPlaylistTracks', item),
  listDirectorSfxCategories: () => ipcRenderer.invoke('director:listSfxCategories'),
  listDirectorSfxFiles: (category) => ipcRenderer.invoke('director:listSfxFiles', category),
  listDirectorSceneSfx: (session, scene) => ipcRenderer.invoke('director:listSceneSfx', { session, scene }),
  sendDirectorCommand: (cmd) => ipcRenderer.invoke('director:sendCommand', cmd)
});
